-- Registers CAD Creator architectural stock fixtures in the canonical studio_templates catalog.
-- Idempotent: deterministic ids, upsert on id.
ON CONFLICT(id) DO UPDATE SET title=excluded.title, description=excluded.description, category=excluded.category, specs_json=excluded.specs_json, pack_slug=excluded.pack_slug, pack_title=excluded.pack_title, sort_order=excluded.sort_order, status=excluded.status, updated_at=unixepoch();
